import pytest

from schedule import (
    Train,
    adjust_departure,
    arrival_times,
    to_hhmm,
    to_minutes,
)


def make_train() -> Train:
    return Train(
        train_id="K1",
        start="08:00",
        legs={"A->B": 10, "B->C": 15},
    )


def test_stop_order() -> None:
    assert make_train().stops() == ["A", "B", "C"]


def test_arrival_times_accumulate() -> None:
    assert arrival_times(make_train()) == {
        "A": "08:00",
        "B": "08:10",
        "C": "08:25",
    }


def test_minute_helpers_roundtrip() -> None:
    assert to_minutes("09:30") == 570
    assert to_hhmm(570) == "09:30"


def test_adjust_departure_recalculates_later_stops() -> None:
    adjusted = adjust_departure(make_train(), "09:30")
    assert isinstance(adjusted, Train)
    assert adjusted.train_id == "K1"
    assert adjusted.start == "09:30"
    assert arrival_times(adjusted) == {
        "A": "09:30",
        "B": "09:40",
        "C": "09:55",
    }


def test_adjust_departure_does_not_mutate_original() -> None:
    original = make_train()
    adjust_departure(original, "09:30")
    assert original.start == "08:00"
    assert arrival_times(original)["C"] == "08:25"


def test_adjust_departure_normalizes_time() -> None:
    assert adjust_departure(make_train(), "9:05").start == "09:05"


def test_adjust_departure_rejects_bad_time() -> None:
    with pytest.raises(ValueError):
        adjust_departure(make_train(), "25:00")
    with pytest.raises(ValueError):
        adjust_departure(make_train(), "not-a-time")


def test_adjust_departure_enforces_current_min_interval() -> None:
    # RULE-01（现行规章）：站间间隔不得低于 3 分钟。
    too_short = Train("K1", "08:00", {"A->B": 2, "B->C": 10})
    with pytest.raises(ValueError):
        adjust_departure(too_short, "09:00")
    boundary = Train("K1", "08:00", {"A->B": 3, "B->C": 10})
    assert adjust_departure(boundary, "09:00").start == "09:00"

